changeSet.sql:
ALTER TABLE modeling_materialization_dispatch ADD CONSTRAINT ck_materialization_dispatch_availability_pin CHECK ( ( availability_pinned_at IS NULL AND availability_pin_count IS NULL ) OR ( availability_pinned_at IS NOT NULL AND availability_pin_count IS NOT NULL AND availability_pin_count >= 0 ) );
ALTER TABLE modeling_materialization_source_pin ADD CONSTRAINT ck_materialization_source_pin CHECK ( asset_type IN ('DATASET', 'DBT_MODEL') AND btrim(asset_key) <> '' AND availability_status = 'AVAILABLE' AND availability_epoch >= 0 AND source_sequence >= 0 AND source_sequence < 9223372036854775807 AND btrim(availability_event_id) <> '' AND btrim(resolved_version) <> '' );
CREATE OR REPLACE FUNCTION modeling_reject_materialization_source_pin_mutation() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN RAISE EXCEPTION 'MODEL_MATERIALIZATION_SOURCE_PIN_APPEND_ONLY' USING ERRCODE = '55000'; END; $function$;
CREATE TRIGGER trg_materialization_source_pin_append_only BEFORE UPDATE OR DELETE ON modeling_materialization_source_pin FOR EACH ROW EXECUTE FUNCTION modeling_reject_materialization_source_pin_mutation();
CREATE TRIGGER trg_materialization_source_pin_no_truncate BEFORE TRUNCATE ON modeling_materialization_source_pin FOR EACH STATEMENT EXECUTE FUNCTION modeling_reject_materialization_source_pin_mutation();
CREATE OR REPLACE FUNCTION modeling_protect_materialization_availability_marker() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN IF OLD.availability_pinned_at IS NOT NULL AND ( NEW.availability_pinned_at IS DISTINCT FROM OLD.availability_pinned_at OR NEW.availability_pin_count IS DISTINCT FROM OLD.availability_pin_count ) THEN RAISE EXCEPTION 'MODEL_MATERIALIZATION_AVAILABILITY_MARKER_IMMUTABLE' USING ERRCODE = '55000'; END IF; RETURN NEW; END; $function$;
CREATE TRIGGER trg_materialization_availability_marker_immutable BEFORE UPDATE OF availability_pinned_at, availability_pin_count ON modeling_materialization_dispatch FOR EACH ROW EXECUTE FUNCTION modeling_protect_materialization_availability_marker();

rollback.sql:
DO $$
BEGIN
    LOCK TABLE modeling_materialization_dispatch,
               modeling_materialization_source_pin
        IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM modeling_materialization_source_pin)
       OR EXISTS (
           SELECT 1
             FROM modeling_materialization_dispatch
            WHERE availability_pinned_at IS NOT NULL
               OR availability_pin_count IS NOT NULL
       ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_MATERIALIZATION_AVAILABILITY_PIN_EXISTS'
            USING ERRCODE = '55000';
    END IF;
END $$;

DROP TRIGGER IF EXISTS trg_materialization_availability_marker_immutable
    ON modeling_materialization_dispatch;
DROP TRIGGER IF EXISTS trg_materialization_source_pin_no_truncate
    ON modeling_materialization_source_pin;
DROP TRIGGER IF EXISTS trg_materialization_source_pin_append_only
    ON modeling_materialization_source_pin;
